#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long a, b;
        cin >> a >> b;
        total += a * b;
    }
    cout << total << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    string line;
    getline(cin, line);  // n 뒤에 남은 줄바꿈을 버려요
    for (int i = 1; i <= n; i++) {
        getline(cin, line);
        cout << i << ": [" << line << "]\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        istringstream iss(line);
        long long x, sum = 0;
        int cnt = 0;
        while (iss >> x) {
            sum += x;
            cnt++;
        }
        cout << cnt << ' ' << sum << '\n';
    }
    return 0;
}
